module rtl_checker #(parameter integer UNIT_W = 2) (
    input logic clk, rst, in_valid, in_ready,
    input logic [4*UNIT_W-1:0] in_data,
    input logic out_valid, out_ready,
    input logic [3*UNIT_W-1:0] out_data
);
    localparam integer DEPTH     = 8;
    localparam integer IN_UNITS  = 4;
    localparam integer OUT_UNITS = 3;
    localparam integer BW        = DEPTH * UNIT_W;
    localparam integer OW        = OUT_UNITS * UNIT_W;
    localparam integer IW        = IN_UNITS * UNIT_W;

    // Private model state
    integer                mcnt  = 0;
    reg [BW-1:0]           mbuf  = '0;
    reg                    minit = 1'b0;

    // History for permitted-scheduling checks
    reg                    pstall = 1'b0;
    reg [OW-1:0]           pout   = '0;
    reg                    pebub  = 1'b0;
    reg                    pvbub  = 1'b0;

    // Blocking temporaries
    integer                room_after;
    integer                c;
    reg                    elig;
    reg                    vbub_now;
    reg [BW-1:0]           base;
    reg [BW-1:0]           ext;

    always @(posedge clk) begin
        // Combinational temporaries from pre-edge state
        room_after = mcnt - ((out_valid && out_ready) ? OUT_UNITS : 0);
        elig       = minit && !rst && (room_after <= DEPTH - IN_UNITS);
        vbub_now   = minit && !rst && !out_valid && (mcnt >= OUT_UNITS);

        // Reset: no input ready while reset is high
        assert(!rst || !in_ready);

        // Output content and validity
        assert(!minit || !out_valid || (mcnt >= OUT_UNITS));
        assert(!minit || !out_valid || (out_data === mbuf[OW-1:0]));

        // Stalled offer must remain unchanged
        assert(!pstall || (out_valid && (out_data === pout)));

        // Input ready: room check
        assert(!minit || !in_ready || (room_after <= DEPTH - IN_UNITS));

        // in_ready may not bubble on two consecutive eligible observations
        assert(!(pebub && elig && !in_ready));

        // out_valid may not bubble on two consecutive observations with >=3 units
        assert(!(pvbub && vbub_now));

        // Model update (nonblocking for persistent state)
        if (rst) begin
            mcnt  <= 0;
            mbuf  <= '0;
            minit <= 1'b1;
            c = 0;
        end else begin
            base = mbuf;
            c    = mcnt;
            if (out_valid && out_ready) begin
                base = base >> (OUT_UNITS * UNIT_W);
                c    = c - OUT_UNITS;
            end
            if (in_valid && in_ready) begin
                ext  = '0;
                ext[IW-1:0] = in_data;
                base = base | (ext << (c * UNIT_W));
                c    = c + IN_UNITS;
            end
            mcnt <= c;
            mbuf <= base;
        end

        // History
        pstall <= minit && out_valid && !out_ready && !rst;
        pout   <= out_data;
        pebub  <= elig && !in_ready;
        pvbub  <= vbub_now;
    end
endmodule

module rtl_checker #(parameter integer UNIT_W = 2) (
    input logic clk, rst, in_valid, in_ready,
    input logic [4*UNIT_W-1:0] in_data,
    input logic out_valid, out_ready,
    input logic [3*UNIT_W-1:0] out_data
);
    localparam integer CAP = 8;

    // Private reference model state (initialized so checks are defined from the start)
    integer cnt = 0;                          // retained units
    logic [8*UNIT_W-1:0] mem = '0;            // retained units, oldest at LSBs
    logic [8*UNIT_W-1:0] mem_n = '0;
    logic prev_stall = 1'b0;                  // previous offer stalled (valid & !ready)
    logic [3*UNIT_W-1:0] prev_out = '0;       // data of previous stalled offer
    logic prev_in_bub = 1'b0;                 // previous obs: eligible and in_ready low
    logic prev_out_bub = 1'b0;                // previous obs: >=3 retained and out_valid low

    // Private scratch (fully assigned before each read in every activation)
    integer base = 0;
    integer keep = 0;
    logic out_hs = 1'b0;
    logic in_hs = 1'b0;
    logic elig = 1'b0;
    logic avail = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            assert(in_ready == 1'b0);
            cnt = 0;
            mem = '0;
            prev_stall = 1'b0;
            prev_in_bub = 1'b0;
            prev_out_bub = 1'b0;
        end else begin
            out_hs = out_valid && out_ready;
            avail = (cnt >= 3);
            base = (out_hs && avail) ? 3 : 0;
            keep = cnt - base;
            elig = (keep <= CAP - 4);

            // in_ready never without room
            assert(!in_ready || elig);
            // no two consecutive eligible observations with in_ready low
            assert(!(prev_in_bub && elig && !in_ready));
            // out_valid only with three retained units
            assert(!out_valid || avail);
            // offered data is the oldest three units
            assert(!out_valid || (out_data == mem[3*UNIT_W-1:0]));
            // stalled offer stays valid with unchanged data
            assert(!prev_stall || out_valid);
            assert(!prev_stall || (out_data == prev_out));
            // no two consecutive low offers with >=3 retained units
            assert(!(prev_out_bub && avail && !out_valid));

            in_hs = in_valid && in_ready;

            // model update: remove oldest units, then append input units
            if (in_hs) begin
                mem_n = (mem >> (UNIT_W * base)) | (in_data << (UNIT_W * keep));
                cnt = keep + 4;
            end else begin
                mem_n = mem >> (UNIT_W * base);
                cnt = keep;
            end
            mem = mem_n;

            // record history for next observation
            prev_stall = out_valid && !out_ready;
            prev_out = out_data;
            prev_in_bub = elig && !in_ready;
            prev_out_bub = avail && !out_valid;
        end
    end

endmodule
